import os
import json
import re

session_base = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/held-out-5/play/users/u000/system/state/sessions"

# Search through all jsonl files for Demo/Test lines with grids
search_count = 0
for filename in sorted(os.listdir(session_base))[:50]:  # Check first 50 files
    filepath = os.path.join(session_base, filename)
    try:
        with open(filepath, 'r') as f:
            lines = f.readlines()

        # Check if this file has "Demo pair" or "Test input" patterns
        for line in lines:
            # Extract message content
            try:
                msg = json.loads(line)
                if 'message' in msg:
                    content = msg['message'].get('content', [])
                    if isinstance(content, list):
                        for item in content:
                            if isinstance(item, dict) and item.get('type') == 'text':
                                text = item.get('text', '')
                                if 'Demo pair' in text or 'Test input' in text:
                                    print(f"\n=== Found in: {filename} ===")
                                    print(f"Line: ...{text[:200]}...")
                                    search_count += 1
                                    break
            except:
                continue

    except Exception as e:
        print(f"Error reading {filename}: {e}")

print(f"\n\nTotal files with Demo/Test patterns: {search_count}")

